"""Summarize verified comparisons with scientific timing and storage measurements."""
from pathlib import Path
import json,datetime,statistics
R=Path(__file__).resolve().parent
s=json.loads((R/'data/comparison/summary.json').read_text());assert s['complete'] and len(s['cases'])==22
objects=json.loads((R/'private/terminal-objects.json').read_text());byname={x['name']:x for x in objects};timings=[]
for c in s['cases']:
 name=c['case'];start=next(x for x in objects if x['name'].endswith('/'+name+'/startup.json'));end=next(x for x in objects if x['name'].endswith('/'+name+'/completion.json'))
 dt=lambda x:datetime.datetime.fromisoformat(x['timeCreated'].replace('Z','+00:00'))
 timings.append(dict(case=name,startup_proof_to_completion_minutes=(dt(end)-dt(start)).total_seconds()/60))
proof=json.loads((R/'data/completed/proof.json').read_text());size=sum(f['bytes'] for c in proof['cases'] for f in c['files']);mins=[x['startup_proof_to_completion_minutes'] for x in timings]
v=json.loads((R/'private/terminal-runtime-pairs.json').read_text());allocation=[(max(x['end'])-min(x['start']))/60 for x in v.values()]
metrics=dict(cases=timings,mean_minutes=statistics.mean(mins),median_minutes=statistics.median(mins),min_minutes=min(mins),max_minutes=max(mins),mean_vm_allocation_minutes=statistics.mean(allocation),scientific_file_bytes=size,private_archive_bytes=sum(int(x['size']) for x in objects),timing_definition='Cloud startup proof creation to completion proof creation: includes full solve, checkpoint stops/transfers and final archive upload; excludes provisioning and initial startup probes. VM allocation additionally includes provisioning/cleanup. Not directly identical to experiment48 reconstructed solver history.')
out=R/'data/report';out.mkdir(exist_ok=True);(out/'measurements.json').write_text(json.dumps(metrics,indent=2)+'\n')
lines=['# Compact-domain comparison: 22 matched single-tree runs','', '**Result: 15 of 22 pass all predeclared screening metrics; 7 exceed at least one threshold. The 24 × 16 m footprint cannot be treated as interchangeable with the original domains across this set.**','', 'All22 completed180 simulated seconds without retries. Each case contains one generic tree from two geometry families, not two trees together. Twenty compact cases use6m crown headroom; two vertical controls use12m. Both vertical controls pass against their matching compact baselines. This does not prove horizontal clearance adequate or establish the cause of each discrepancy.','', '## Every matched result','', 'Percent changes are compact minus original, divided by original. History L1 is integrated absolute HRR difference divided by original energy. Wet mass loss includes drying and pyrolysis. Hot MAE uses the union of cells at least50°C in the aligned common region.','', '|Case|Total energy Δ%|Post20 energy Δ%|Peak HRR Δ%|History L1 %|Wet loss Δpp|Hot MAE °C|Peak-history MAE °C|Screen|','|---|---:|---:|---:|---:|---:|---:|---:|---|']
for c in s['cases']:
 m=c['metrics'];f=c['temperature'];lines.append(f"|{c['case'].replace('tree49_','')}|{m['total_energy_relative_difference']*100:.2f}|{m['post20_energy_relative_difference']*100:.2f}|{m['peak_hrr_relative_difference']*100:.2f}|{m['hrr_history_relative_L1']*100:.2f}|{m['wet_mass_loss_difference_percentage_points']:.3f}|{f['common_region_hot_temperature_mae_C']:.2f}|{f['peak_temperature_history_mae_C']:.2f}|{'FLAG' if c['major_discrepancy_flags'] else 'pass'}|")
lines+=['','Thresholds unchanged:10% total/post20 energy,20% peak HRR/history L1,2percentage points wet-mass-loss difference,100°C hot-region/peak-history MAE. These are engineering screening tolerances, not statistical equivalence or physical validation.','', '## Post-source energy in absolute units','', '|Case|Original post20 kJ|Compact post20 kJ|Difference kJ|','|---|---:|---:|---:|']
for c in s['cases']:
 m=c['metrics'];a=m['original_post20_energy_kj'];b=m['compact_post20_energy_kj'];lines.append(f"|{c['case'].replace('tree49_','')}|{a:.2f}|{b:.2f}|{b-a:+.2f}|")
lines+=['','HRR integrates combustion within each gas domain. The smaller domain can let burning gas leave earlier, changing this integral as well as flow; these measurements alone do not identify the mechanism. Cases000997 and001991 also exceed100°C common-region hot-temperature MAE, so global integration volume is not the only observed difference.','', '## Extra-height controls','']
for c in s['vertical_controls']:
 lines.append(f"- {c['height_control']}: energy change {100*c['metrics']['total_energy_relative_difference']:+.3f}%, hot-region MAE {c['temperature']['common_region_hot_temperature_mae_C']:.3f}°C versus its compact baseline; all metrics pass.")
lines+=['','## Measured runtime and storage','',f"Startup-proof to completion averaged **{statistics.mean(mins):.2f}min**, median {statistics.median(mins):.2f}min, range {min(mins):.2f}–{max(mins):.2f}min. This includes full solving, checkpoint transfers and final archive upload, but excludes provisioning and initial probes. Mean actual VM allocation was {statistics.mean(allocation):.2f}min including provisioning and cleanup.",'', 'For context, the earlier22 large-domain runs averaged85.5min using reconstructed solver history, and the original32 small single-crown training runs averaged6.23min. These timing definitions/workloads differ, so their ratio is not a controlled speedup measurement.', '',f"Scientific solve files total {size/1e9:.3f}GB. The complete private cloud inventory, including checkpoint history and operational evidence, totals {metrics['private_archive_bytes']/1e9:.3f}GB. Original outputs remain preserved.",'', '## Scope and limitations','', 'The0.5m mesh,180s target, fuel weights, moisture, wind, chemistry and relative geometry were preserved. Domains became24×16m with24–32m height, or30/34m for controls. Trees are generic wood/crown18–26m species-inspired shapes with static burning woody particles, not validated species or resolved solid trunks. No bark, embers or grass. Ignition is an imposed0.4×0.4m1500°C20s patch, not natural ignition. Fine-grid tests were cancelled; grid convergence is not established.','', 'Temperature comparisons use six3D snapshots approximately36s apart. DT_SLCF=2s did not set3D output frequency; FDS uses its default DT_SL3D=36s. The checker’s incorrect80-frame expectation was corrected, with discrepancy thresholds unchanged. Sparse sampling cannot exclude brief differences between frames. All44 original/new temperature files were independently checked at180s using fds2ascii; cell-centered alignment was checked against the writer implementation. Old snapshots were linearly interpolated to new saved times.','', 'All22 result archives and all437 cloud objects passed generation-pinned MD5/SHA verification. Both Batch waves succeeded. Jobs, VMs and disks were independently confirmed empty; the exact experiment read grant was removed. Private accounting remains private.','']
(out/'report.md').write_text('\n'.join(lines));print(json.dumps({k:v for k,v in metrics.items() if k!='cases'},indent=2))
